import sys
input = sys.stdin.readline

def solve():
    s = input().strip()
    n = len(s)
    if n % 2 == 1:
        print("NO")
        return

    # Precompute suffix sums
    suffix_open = [0] * (n + 1)
    suffix_close = [0] * (n + 1)
    suffix_q = [0] * (n + 1)

    for i in range(n - 1, -1, -1):
        suffix_open[i] = suffix_open[i + 1] + (1 if s[i] == '(' else 0)
        suffix_close[i] = suffix_close[i + 1] + (1 if s[i] == ')' else 0)
        suffix_q[i] = suffix_q[i + 1] + (1 if s[i] == '?' else 0)

    def is_feasible(new_bal, i):
        """Check if completion is possible after assigning at position i with balance new_bal."""
        if new_bal < 0:
            return False
        rq = suffix_q[i + 1]
        ro = suffix_open[i + 1]
        rc = suffix_close[i + 1]
        needed = rq - new_bal - ro + rc  # = 2 * assigned_open
        return needed >= 0 and needed <= 2 * rq and needed % 2 == 0

    def construct(prefer_open):
        """Construct a valid RBS, preferring '(' or ')' for each '?'."""
        result = []
        balance = 0
        for i in range(n):
            if s[i] == '(':
                balance += 1
                result.append('(')
            elif s[i] == ')':
                balance -= 1
                result.append(')')
            else:  # '?'
                if prefer_open:
                    if is_feasible(balance + 1, i):
                        balance += 1
                        result.append('(')
                    else:
                        balance -= 1
                        result.append(')')
                else:
                    if is_feasible(balance - 1, i):
                        balance -= 1
                        result.append(')')
                    else:
                        balance += 1
                        result.append('(')
        return ''.join(result)

    g1 = construct(True)   # prefer '('
    g2 = construct(False)  # prefer ')'

    print("YES" if g1 == g2 else "NO")

t = int(input())
for _ in range(t):
    solve()
